package com.gielinorgoals.model;

import lombok.Value;

/**
 * Oföränderlig ögonblicksbild av hur långt ett automatiskt mål har kommit.
 */
@Value
public class GoalProgress
{
	long current;
	long target;
	boolean complete;
	// Kort text för progressbaren, t.ex. "57/70" eller "1.2M/13M".
	String label;

	/**
	 * Andel klar mellan 0 och 1.
	 */
	public double fraction()
	{
		if (complete || target <= 0)
		{
			return complete ? 1.0 : 0.0;
		}
		return Math.max(0.0, Math.min(1.0, (double) current / target));
	}
}

